import { StyleSheet, View, type ColorValue } from 'react-native';

/**
 * TARSMusic mark: TARS's four slabs as a centred waveform. Each slab is split into two blocks at
 * `SLAB_SPLITS[i]` of its height. These match the SVG logo generated by scripts/generate-assets.js.
 */
export const BAR_HEIGHTS = [0.5, 1.0, 0.74, 0.36];
export const SLAB_SPLITS = [0.5, 0.38, 0.62, 0.5];

/** Gap between a slab's two blocks, as a fraction of the logo size. */
export const SLAB_GAP_RATIO = 0.04;

/** Gap as a fraction of bar width. */
const GAP_RATIO = 0.55;

const BAR_COUNT = BAR_HEIGHTS.length;

type Props = {
  /** Overall size (dp) – the tallest bar will be this height. */
  size?: number;
  /** Bar colour. Accepts any RN `ColorValue` so the tab-icon callback's
   *  `OpaqueColorValue` (SDK 56 / RN 0.85 typing tightening) flows in. */
  color?: ColorValue;
};

export default function WaveformLogo({ size = 130, color = '#FFFFFF' }: Props) {
  const barWidth = size / (BAR_COUNT + (BAR_COUNT - 1) * GAP_RATIO);
  const gap = barWidth * GAP_RATIO;

  return (
    <View style={styles.wrap}>
      {BAR_HEIGHTS.map((h, i) => (
        <Slab
          key={i}
          width={barWidth}
          height={size * h}
          split={SLAB_SPLITS[i]}
          blockGap={size * SLAB_GAP_RATIO}
          color={color}
          marginLeft={i === 0 ? 0 : gap}
        />
      ))}
    </View>
  );
}

/** One TARS slab: two stacked blocks with a small gap. */
export function Slab({
  width,
  height,
  split,
  blockGap,
  color,
  marginLeft,
}: {
  width: number;
  height: number;
  split: number;
  blockGap: number;
  color: ColorValue;
  marginLeft: number;
}) {
  const radius = width * 0.12;
  const top = Math.max(0, height * split - blockGap / 2);
  const bottom = Math.max(0, height - top - blockGap);
  return (
    <View style={{ width, height, marginLeft, justifyContent: 'space-between' }}>
      <View style={{ height: top, borderRadius: radius, backgroundColor: color }} />
      <View style={{ height: bottom, borderRadius: radius, backgroundColor: color }} />
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
  },
});
